import { createReadStream, stat } from 'node:fs';
import path from 'node:path';
import react from '@vitejs/plugin-react';
import { defineConfig, type Plugin } from 'vite';
import { configDefaults } from 'vitest/config';

// Serve the geodata assets (geodata/assets/) at /geodata/ in dev and
// preview, so the look-dev routes read the same bytes the Go server
// will serve in production without duplicating them into web/public.
// The terrarium DEM tiles and the self-built PMTiles basemap are
// gitignored locals regenerated by their scripts; the committed
// vectors ship the same way they always have. Range requests are
// honoured because the PMTiles client reads tiles by byte range (a
// full-file body per tile would be catastrophic). The production build
// does not include them: which assets ship with the product is a
// Phase 4 decision.
function geodata(): Plugin {
  const root = path.resolve(import.meta.dirname, '../geodata/assets');
  const mime: Record<string, string> = {
    '.png': 'image/png',
    '.json': 'application/json',
    '.geojson': 'application/json',
    '.pmtiles': 'application/octet-stream',
  };
  const serve = (
    req: { url?: string; headers?: { range?: string } },
    res: {
      statusCode: number;
      setHeader: (k: string, v: string | number) => void;
      end: () => void;
    },
    next: () => void,
  ) => {
    const rel = decodeURIComponent((req.url ?? '').split('?')[0]).replace(/^\/+/, '');
    const file = path.join(root, rel);
    if (!file.startsWith(root) || rel.includes('..')) {
      res.statusCode = 403;
      res.end();
      return;
    }
    stat(file, (err, st) => {
      if (err || !st.isFile()) {
        next();
        return;
      }
      const range = req.headers?.range;
      const match = /^bytes=(\d*)-(\d*)$/.exec(range ?? '');
      if (range && match) {
        const start = match[1] ? Number(match[1]) : 0;
        const end = match[2] ? Math.min(Number(match[2]), st.size - 1) : st.size - 1;
        if (Number.isNaN(start) || Number.isNaN(end) || start > end || start >= st.size) {
          res.statusCode = 416;
          res.setHeader('Content-Range', `bytes */${st.size}`);
          res.end();
          return;
        }
        res.statusCode = 206;
        res.setHeader('Content-Range', `bytes ${start}-${end}/${st.size}`);
        res.setHeader('Content-Length', end - start + 1);
        res.setHeader('Content-Type', mime[path.extname(file)] ?? 'application/octet-stream');
        createReadStream(file, { start, end }).pipe(res as never);
        return;
      }
      res.statusCode = 200;
      res.setHeader('Content-Type', mime[path.extname(file)] ?? 'application/octet-stream');
      res.setHeader('Content-Length', st.size);
      res.setHeader('Accept-Ranges', 'bytes');
      createReadStream(file).pipe(res as never);
    });
  };
  return {
    name: 'geodata',
    configureServer(server) {
      server.middlewares.use('/geodata', serve as never);
    },
    configurePreviewServer(server) {
      server.middlewares.use('/geodata', serve as never);
    },
  };
}

// The Go server serves the built files and the API on one origin in
// production. In development, Vite proxies /api to the Go server so the
// browser sees the same single origin.
export default defineConfig({
  plugins: [react(), geodata()],
  server: {
    port: 5173,
    strictPort: true,
    proxy: {
      '/api': 'http://127.0.0.1:8080',
      '/healthz': 'http://127.0.0.1:8080',
    },
  },
  preview: {
    port: 4173,
    strictPort: true,
  },
  build: {
    target: 'es2022',
    sourcemap: true,
  },
  test: {
    // Pure logic (formatters, search, nearest station, timeline decoding)
    // runs in Node. Component tests can opt into a DOM per file later.
    environment: 'node',
    include: ['src/**/*.test.{ts,tsx}'],
    exclude: [...configDefaults.exclude, '**/._*'],
  },
});
